/**
 * Generated spec for Epic SCRUM-17: Customer profile and orders
 * Stories: SCRUM-24, SCRUM-25
 *
 * NOTE: bdd2pw scaffold was blocked because the shared feature file contains
 * pre-existing SCRUM-24 steps using custom vocabulary that bdd2pw cannot bind
 * (e.g. "Given I am logged in as a registered customer", "fill in the address
 * form…"). Those steps belong to SCRUM-24 and cannot be reworded or removed
 * without dropping another story's scenarios — a write that drops them is
 * refused. This spec therefore implements ALL steps directly.
 */
import { test, expect } from "@playwright/test";
import AxeBuilder from "@axe-core/playwright";

// ---------------------------------------------------------------------------
// Shared helpers
// ---------------------------------------------------------------------------

/** Sign in with the standard test account and wait for the account menu. */
async function loginAsRegisteredCustomer(page: import("@playwright/test").Page) {
  await page.goto("/#/login");

  const dismissBtn = page.getByRole("button", { name: "dismiss cookie message" });
  await dismissBtn.waitFor({ state: "visible", timeout: 4000 }).catch(() => {});
  if (await dismissBtn.isVisible()) await dismissBtn.click();

  await page.getByLabel("Email").fill(process.env["AQA_APP_USER"] ?? "");
  await page.locator("input[type='password']").fill(process.env["AQA_APP_PASS"] ?? "");
  await page.getByRole("button", { name: "Login" }).click();

  await expect(
    page.getByRole("button", { name: "Show/hide account menu" }),
    "Precondition: login must succeed before navigating to Change Password"
  ).toBeVisible({ timeout: 10000 });
}

// ---------------------------------------------------------------------------
// SCRUM-25 — Customer changes their password
// ---------------------------------------------------------------------------
// The comment block refers to a dedicated test account whose password is reset
// after each password-change test so other stories keep working.
// The reset is done by changing back to the original password at the end of
// each test that changes it, using the new credentials.
// ---------------------------------------------------------------------------

test.describe("Customer profile and orders – Change Password (SCRUM-25)", () => {

  // @story:SCRUM-25 @ac:1 @design:D6 @type:functional @technique:state-transition
  test("AC-1 Correct current password and matching new password changes the password and shows confirmation", async ({ page }) => {
    await test.step("Given I am logged in as a registered customer", async () => {
      await loginAsRegisteredCustomer(page);
    });

    await test.step("When I navigate to the Change Password page", async () => {
      await page.goto("/#/privacy-security/change-password");
      await expect(page.getByRole("heading", { name: "Change Password" })).toBeVisible({ timeout: 5000 });
    });

    await test.step("And I enter the current password", async () => {
      await page.getByLabel("Field to enter the current password").fill(process.env["AQA_APP_PASS"] ?? "");
    });

    const newPassword = "NewPass@99";

    await test.step("And I enter the new password", async () => {
      await page.getByLabel("Field for the new password").fill(newPassword);
    });

    await test.step("And I repeat the new password", async () => {
      await page.getByLabel("Field to repeat the new password").fill(newPassword);
    });

    await test.step("And I click Change", async () => {
      await page.getByRole("button", { name: "Button to confirm the change" }).click();
    });

    await test.step("Then the page displays a password-changed confirmation", async () => {
      await expect(page.getByText("Password successfully changed")).toBeVisible({ timeout: 10000 });
    });

    // Reset the password back so other tests / stories keep working
    await test.step("Teardown: reset password back to original", async () => {
      await page.getByLabel("Field to enter the current password").fill(newPassword);
      await page.getByLabel("Field for the new password").fill(process.env["AQA_APP_PASS"] ?? "");
      await page.getByLabel("Field to repeat the new password").fill(process.env["AQA_APP_PASS"] ?? "");
      await page.getByRole("button", { name: "Button to confirm the change" }).click();
      await expect(page.getByText("Password successfully changed")).toBeVisible({ timeout: 10000 });
    });
  });

  // @story:SCRUM-25 @ac:2 @design:D7 @type:functional @technique:equivalence-partitioning
  test("AC-2 Wrong current password causes the change to be refused with a message", async ({ page }) => {
    await test.step("Given I am logged in as a registered customer", async () => {
      await loginAsRegisteredCustomer(page);
    });

    await test.step("When I navigate to the Change Password page", async () => {
      await page.goto("/#/privacy-security/change-password");
      await expect(page.getByRole("heading", { name: "Change Password" })).toBeVisible({ timeout: 5000 });
    });

    await test.step("And I enter a wrong current password", async () => {
      await page.getByLabel("Field to enter the current password").fill("WrongPassword999!");
    });

    await test.step("And I enter a new password", async () => {
      await page.getByLabel("Field for the new password").fill("NewPass@99");
    });

    await test.step("And I repeat the new password", async () => {
      await page.getByLabel("Field to repeat the new password").fill("NewPass@99");
    });

    await test.step("And I click Change", async () => {
      await page.getByRole("button", { name: "Button to confirm the change" }).click();
    });

    await test.step("Then the page displays 'Current password is not correct'", async () => {
      await expect(page.getByText("Current password is not correct")).toBeVisible({ timeout: 10000 });
    });
  });

  // @story:SCRUM-25 @ac:3 @design:D8 @type:functional @technique:equivalence-partitioning
  test("AC-3 New password and repeat that differ causes the Change button to be disabled", async ({ page }) => {
    await test.step("Given I am logged in as a registered customer", async () => {
      await loginAsRegisteredCustomer(page);
    });

    await test.step("When I navigate to the Change Password page", async () => {
      await page.goto("/#/privacy-security/change-password");
      await expect(page.getByRole("heading", { name: "Change Password" })).toBeVisible({ timeout: 5000 });
    });

    await test.step("And I enter the current password", async () => {
      await page.getByLabel("Field to enter the current password").fill(process.env["AQA_APP_PASS"] ?? "");
    });

    await test.step("And I enter a new password", async () => {
      await page.getByLabel("Field for the new password").fill("NewPass@99");
    });

    await test.step("And I enter a different value in the repeat field", async () => {
      await page.getByLabel("Field to repeat the new password").fill("DifferentPass!77");
    });

    await test.step("Then the Change button is disabled", async () => {
      await expect(
        page.getByRole("button", { name: "Button to confirm the change" })
      ).toBeDisabled();
    });
  });

  // @story:SCRUM-25 @ac:1 @design:D9 @type:security @technique:state-transition
  test("AC-1b After password change the old password no longer works", async ({ page }) => {
    const newPassword = "SecureNew@55";

    await test.step("Given I am logged in as a registered customer", async () => {
      await loginAsRegisteredCustomer(page);
    });

    await test.step("When I navigate to the Change Password page", async () => {
      await page.goto("/#/privacy-security/change-password");
      await expect(page.getByRole("heading", { name: "Change Password" })).toBeVisible({ timeout: 5000 });
    });

    await test.step("And I change the password to a new value", async () => {
      await page.getByLabel("Field to enter the current password").fill(process.env["AQA_APP_PASS"] ?? "");
      await page.getByLabel("Field for the new password").fill(newPassword);
      await page.getByLabel("Field to repeat the new password").fill(newPassword);
      await page.getByRole("button", { name: "Button to confirm the change" }).click();
    });

    await test.step("Then the page confirms the password was changed", async () => {
      await expect(page.getByText("Password successfully changed")).toBeVisible({ timeout: 10000 });
    });

    await test.step("When I log out", async () => {
      await page.getByRole("button", { name: "Show/hide account menu" }).click();
      await page.getByRole("menuitem", { name: "Logout" }).click();
      await expect(page).toHaveURL(/\/#\//, { timeout: 10000 });
    });

    await test.step("And I try to log in with the old password", async () => {
      await page.goto("/#/login");
      await page.getByLabel("Email").fill(process.env["AQA_APP_USER"] ?? "");
      await page.locator("input[type='password']").fill(process.env["AQA_APP_PASS"] ?? "");
      await page.getByRole("button", { name: "Login" }).click();
    });

    await test.step("Then the login is refused with an error message", async () => {
      await expect(page.getByText("Invalid email or password.")).toBeVisible({ timeout: 10000 });
    });

    // Teardown: restore the original password using the new one
    await test.step("Teardown: restore original password", async () => {
      await page.getByLabel("Email").fill(process.env["AQA_APP_USER"] ?? "");
      await page.locator("input[type='password']").fill(newPassword);
      await page.getByRole("button", { name: "Login" }).click();
      await expect(
        page.getByRole("button", { name: "Show/hide account menu" })
      ).toBeVisible({ timeout: 10000 });
      await page.goto("/#/privacy-security/change-password");
      await page.getByLabel("Field to enter the current password").fill(newPassword);
      await page.getByLabel("Field for the new password").fill(process.env["AQA_APP_PASS"] ?? "");
      await page.getByLabel("Field to repeat the new password").fill(process.env["AQA_APP_PASS"] ?? "");
      await page.getByRole("button", { name: "Button to confirm the change" }).click();
      await expect(page.getByText("Password successfully changed")).toBeVisible({ timeout: 10000 });
    });
  });

  // @story:SCRUM-25 @design:D10 @type:accessibility @technique:checklist-based
  test("AC-story Accessibility of the Change Password form", async ({ page }) => {
    await test.step("Given I am logged in as a registered customer", async () => {
      await loginAsRegisteredCustomer(page);
    });

    await test.step("When I navigate to the Change Password page", async () => {
      await page.goto("/#/privacy-security/change-password");
      await expect(page.getByRole("heading", { name: "Change Password" })).toBeVisible({ timeout: 5000 });
    });

    await test.step("Then the page passes axe accessibility checks", async () => {
      const results = await new AxeBuilder({ page })
        .include("app-change-password, mat-card, form, .mat-card")
        .withTags(["wcag2a", "wcag2aa"])
        .analyze();
      expect(
        results.violations.map((v) => v.id).sort(),
        "axe-core WCAG A/AA violations on the Change Password page"
      ).toEqual([]);
    });
  });

});

/**
 * Generated from: features/epic-scrum-17-customer-profile-and-orders.feature
