// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Sign in using the test account credentials from environment variables. */
async function loginAsRegisteredCustomer(page: import("@playwright/test").Page) {
  await page.goto("/#/login");
  await page.getByLabel("Email").fill(process.env["AQA_APP_USER"] ?? "");
  await page.locator("input[type='password']").fill(process.env["AQA_APP_PASS"] ?? "");
  await page.getByRole("button", { name: "Login" }).click();
  // Precondition: confirm login succeeded before proceeding
  await expect(
    page.getByRole("button", { name: "Show/hide account menu" }),
    "Precondition: login must succeed — check AQA_APP_USER / AQA_APP_PASS"
  ).toBeVisible({ timeout: 10000 });
}

/** Dismiss cookie consent and welcome banner if present (idempotent). */
async function dismissOverlays(page: import("@playwright/test").Page) {
  const cookie = page.getByRole("button", { name: "dismiss cookie message" });
  await cookie.waitFor({ state: "visible", timeout: 4000 }).catch(() => {});
  if (await cookie.isVisible()) await cookie.click();

  const banner = page.getByRole("button", { name: "Close Welcome Banner" });
  await banner.waitFor({ state: "visible", timeout: 4000 }).catch(() => {});
  if (await banner.isVisible()) await banner.click();
}

